	 * @see https://www.chilkatsoft.com/refdoc/phpCkXmlRef.html#UpdateChildContent
	 * @param ?string $tagPath
	 * @param ?string $value
	 */
	function UpdateChildContent($tagPath,$value) {
		CkXml_UpdateChildContent($this->_cPtr,$tagPath,$value);
	}

	/**
	 * Sets the content of the child selected by tagPath to the decimal representation of integer value. Tag paths: A tag path is Chilkat's |-separated child-navigation syntax, for example tagA|tagB|tagC. It is not XPath.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkXmlRef.html#UpdateChildContentInt
	 * @param ?string $tagPath
	 * @param int $value
	 */
	function UpdateChildContentInt($tagPath,$value) {
		CkXml_UpdateChildContentInt($this->_cPtr,$tagPath,$value);
	}

	/**
	 * ZIP-compresses this element's text content and replaces the original content with Base64-encoded compressed data. Returns _TRUE_ on success and _FALSE_ on failure.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkXmlRef.html#ZipContent
	 * @return bool
	 */
	function ZipContent() {
		return CkXml_ZipContent($this->_cPtr);
	}

	/**
	 * ZIP-compresses the calling element's content together with its entire child subtree and replaces that structure with Base64-encoded compressed data. The calling element's tag and attributes are not changed. Call UnzipTree to reconstruct the compressed subtree.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkXmlRef.html#ZipTree
	 * @return bool
	 */
	function ZipTree() {
		return CkXml_ZipTree($this->_cPtr);
	}
}
